#include <stdio.h>

int main() {
    int marks[5];

    for (int i = 0; i < 5; i++) {
        printf("Enter mark %d: ", i + 1);
        scanf("%d", &marks[i]);
    }
    for (int i = 0; i < 5; i++) {
        printf("Subject %d: %d\n", i + 1, marks[i]);
    }
    return 0;
}

codeFiles.source:
#include <stdio.h>

int main() {
    int marks[5] = {78, 92, 65, 88, 71};

    printf("First mark: %d\n", marks[0]);
    printf("Last mark: %d\n", marks[4]);

    marks[2] = 70;

    for (int i = 0; i < 5; i++) {
        printf("marks[%d] = %d\n", i, marks[i]);
    }
    return 0;
}

#include <stdio.h>

int main() {
    int a[5] = {1, 2};
    int b[] = {4, 5, 6};

    for (int i = 0; i < 5; i++) {
        printf("%d ", a[i]);
    }
    printf("\n");
    printf("%d %d %d\n", b[0], b[1], b[2]);
    return 0;
}

#include <stdio.h>

int main() {
    int a[3] = {1, 2, 3};
    int b[3];
    b = a;
    return 0;
}

#include <stdio.h>

int main() {
    int a[3] = {1, 2, 3};
    int b[3];

    for (int i = 0; i < 3; i++) {
        b[i] = a[i];
    }
    printf("%d %d %d\n", b[0], b[1], b[2]);
    return 0;
}
